<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Product;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class StoreApiController extends Controller {public function products(Request $request){$query=Product::where('publication_status',1);if($request->filled('updated_since'))$query->where('updated_at','>=',$request->updated_since);return response()->json($query->select('id','sku','product_name','offer_price','regular_price','purchase_price','product_condition','stock_quantity','stock_tracking','updated_at')->selectRaw(Product::sellingPriceSql().' selling_price')->paginate(min(100,max(1,(int)$request->input('per_page',50)))));}
public function orders(Request $request){$query=DB::table('orders')->latest();if($request->filled('updated_since'))$query->where('updated_at','>=',$request->updated_since);if($request->filled('status'))$query->where('status',$request->status);return response()->json($query->paginate(min(100,max(1,(int)$request->input('per_page',50)))));}
public function order($id){$order=DB::table('orders')->where('id',$id)->first();if(!$order)return response()->json(['error'=>'Order not found.'],404);$order->items=DB::table('order_items')->where('order_id',$id)->get();return response()->json($order);}
public function updateInventory(Request $request,$id){$this->validate($request,['stock_quantity'=>'required|integer|min:0|max:100000']);$product=Product::find($id);if(!$product)return response()->json(['error'=>'Product not found.'],404);$quantity=(int)$request->stock_quantity;DB::transaction(function()use($product,$quantity){$location=DB::table('inventory_locations')->where('is_default',1)->where('is_active',1)->lockForUpdate()->first();if(!$location)throw new \RuntimeException('No active default inventory location is configured.');$balance=DB::table('product_location_stock')->where('location_id',$location->id)->where('product_id',$product->id)->lockForUpdate()->first();if($balance)DB::table('product_location_stock')->where('id',$balance->id)->update(['quantity'=>$quantity,'updated_at'=>now()]);else DB::table('product_location_stock')->insert(['location_id'=>$location->id,'product_id'=>$product->id,'quantity'=>$quantity,'created_at'=>now(),'updated_at'=>now()]);$total=(int)DB::table('product_location_stock')->where('product_id',$product->id)->sum('quantity');DB::table('product')->where('id',$product->id)->update(['stock_tracking'=>1,'stock_quantity'=>$total,'product_condition'=>$total>0?'In Stock':'Out Of Stock','updated_at'=>now()]);});$product->refresh();app(\App\Services\WebhookService::class)->dispatch('inventory.updated',['product_id'=>$product->id,'sku'=>$product->sku,'stock_quantity'=>$product->stock_quantity,'condition'=>$product->product_condition]);return response()->json(['data'=>$product->only(['id','sku','stock_quantity','product_condition','updated_at'])]);}}
